import covers from "./blog-covers.json";

// Cover image per post, generated by scripts/render-blog-covers.mjs into
// public/blog/covers/. "screen" covers show a real app screen from the Emerald
// Bites Café demo account (captured 2026-11-13, test data, said on the image);
// "card" covers are branded topic cards for legal, fiscal-risk, staff and money
// posts. A post with no entry falls back to BlogTopicHeader's topic icon.
// After adding a post, run: node scripts/render-blog-covers.mjs

export type BlogCover = { src: string; kind: "screen" | "card"; alt: string };

const COVERS = covers as Record<string, BlogCover>;

export function blogCoverFor(slug: string): BlogCover | undefined {
  return COVERS[slug];
}
